-- Task 10 phase 1 is outage-only.  Evidence is not reconstructable.
LOCK TABLE control_plane.entitlements IN ACCESS EXCLUSIVE MODE;
LOCK TABLE control_plane.did_mappings IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM control_plane.entitlements) THEN RAISE EXCEPTION '0005 requires quiesced writers and zero entitlement rows'; END IF; END $$;

CREATE TABLE control_plane.revocation_evidence_key_ids (key_id text PRIMARY KEY CHECK(key_id ~ '^[a-z][a-z0-9_-]{0,31}$'), enabled boolean NOT NULL);
CREATE TABLE control_plane.membership_access_states (mapping_id uuid PRIMARY KEY REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT,barrier_state text NOT NULL CHECK(barrier_state IN ('active','suspended')),revision bigint NOT NULL CHECK(revision>=0),current_operation_id uuid,changed_at timestamptz NOT NULL,cause_request_id uuid);
INSERT INTO control_plane.membership_access_states(mapping_id,barrier_state,revision,changed_at) SELECT id,'active',0,clock_timestamp() FROM control_plane.did_mappings;
CREATE TABLE control_plane.entitlement_evidence_aliases (entitlement_id uuid NOT NULL REFERENCES control_plane.entitlements(id) ON DELETE CASCADE,evidence_kind text NOT NULL CHECK(evidence_kind IN ('issuer','issuer_key','policy')),fingerprint_key_id text NOT NULL REFERENCES control_plane.revocation_evidence_key_ids(key_id) ON DELETE RESTRICT,fingerprint bytea NOT NULL CHECK(octet_length(fingerprint)=32),PRIMARY KEY(entitlement_id,evidence_kind,fingerprint_key_id));

CREATE TABLE control_plane.membership_access_sources (id uuid PRIMARY KEY,source_kind text NOT NULL CHECK(source_kind IN ('entitlement_expiry','signed_policy_revocation','authenticated_issuer_revocation','authenticated_key_compromise','authenticated_lost_device')),reason text NOT NULL CHECK(reason IN ('entitlement_expired','policy_revoked','issuer_revoked','issuer_key_compromise','lost_device')),producer_id text NOT NULL CHECK(octet_length(producer_id) BETWEEN 1 AND 255),source_event_id uuid NOT NULL,source_event_digest bytea NOT NULL CHECK(octet_length(source_event_digest)=32),requested_at timestamptz NOT NULL,source_effective_at timestamptz NOT NULL,mapping_id uuid REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT,publication_state text NOT NULL DEFAULT 'pending' CHECK(publication_state IN ('pending','publishing','published','failed')),created_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),cursor_digest bytea CHECK(cursor_digest IS NULL OR octet_length(cursor_digest)=32),chunk_count integer NOT NULL DEFAULT 0 CHECK(chunk_count>=0),finalized_at timestamptz,UNIQUE(producer_id,source_kind,source_event_id),CHECK(requested_at>=source_effective_at),CHECK((source_kind IN ('entitlement_expiry','authenticated_lost_device') AND mapping_id IS NOT NULL) OR (source_kind NOT IN ('entitlement_expiry','authenticated_lost_device') AND mapping_id IS NULL)),CHECK((publication_state='published')=(finalized_at IS NOT NULL)));
CREATE TABLE control_plane.membership_access_source_chunks (source_id uuid NOT NULL REFERENCES control_plane.membership_access_sources(id) ON DELETE RESTRICT,chunk_no integer NOT NULL CHECK(chunk_no>=0),target_count integer NOT NULL CHECK(target_count>=0),chunk_digest bytea NOT NULL CHECK(octet_length(chunk_digest)=32),published_at timestamptz NOT NULL,PRIMARY KEY(source_id,chunk_no));
CREATE TABLE control_plane.membership_access_source_selector_aliases (source_id uuid NOT NULL REFERENCES control_plane.membership_access_sources(id) ON DELETE RESTRICT,selector_kind text NOT NULL CHECK(selector_kind IN ('issuer','issuer_key','policy','mapping')),fingerprint_key_id text NOT NULL REFERENCES control_plane.revocation_evidence_key_ids(key_id) ON DELETE RESTRICT,fingerprint bytea NOT NULL CHECK(octet_length(fingerprint)=32),PRIMARY KEY(source_id,selector_kind,fingerprint_key_id));
CREATE TABLE control_plane.membership_access_source_cause_aliases (source_id uuid NOT NULL REFERENCES control_plane.membership_access_sources(id) ON DELETE RESTRICT,fingerprint_key_id text NOT NULL REFERENCES control_plane.revocation_evidence_key_ids(key_id) ON DELETE RESTRICT,fingerprint bytea NOT NULL CHECK(octet_length(fingerprint)=32),PRIMARY KEY(source_id,fingerprint_key_id));
CREATE TABLE control_plane.membership_access_source_targets (source_id uuid NOT NULL REFERENCES control_plane.membership_access_sources(id) ON DELETE RESTRICT,mapping_id uuid NOT NULL REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT,chunk_no integer NOT NULL CHECK(chunk_no>=0),PRIMARY KEY(source_id,mapping_id),FOREIGN KEY(source_id,chunk_no) REFERENCES control_plane.membership_access_source_chunks(source_id,chunk_no) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED);

CREATE TABLE control_plane.membership_access_operations (id uuid PRIMARY KEY,mapping_id uuid NOT NULL REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT,transition_revision bigint NOT NULL CHECK(transition_revision>0),state text NOT NULL CHECK(state IN ('local_enforced','reconciling','blocked','completed')),first_effective_at timestamptz NOT NULL,local_enforced_at timestamptz,completed_at timestamptz,blocked_code text CHECK(blocked_code ~ '^[a-z][a-z0-9_]{0,63}$'),UNIQUE(id,mapping_id,transition_revision),UNIQUE(id,mapping_id),UNIQUE(mapping_id,transition_revision),CHECK((state='completed')=(completed_at IS NOT NULL)),CHECK((state='blocked')=(blocked_code IS NOT NULL)));
ALTER TABLE control_plane.membership_access_states ADD CONSTRAINT membership_access_state_operation_fk FOREIGN KEY(current_operation_id,mapping_id,revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE control_plane.membership_access_requests (id uuid PRIMARY KEY,source_id uuid NOT NULL,mapping_id uuid NOT NULL,operation_id uuid NOT NULL,created_at timestamptz NOT NULL,UNIQUE(source_id,mapping_id),FOREIGN KEY(source_id,mapping_id) REFERENCES control_plane.membership_access_source_targets(source_id,mapping_id) ON DELETE RESTRICT,FOREIGN KEY(operation_id,mapping_id) REFERENCES control_plane.membership_access_operations(id,mapping_id) ON DELETE RESTRICT);
ALTER TABLE control_plane.membership_access_states ADD CONSTRAINT membership_access_state_cause_fk FOREIGN KEY(cause_request_id) REFERENCES control_plane.membership_access_requests(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE control_plane.membership_access_mas_targets (id uuid PRIMARY KEY,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,kind text NOT NULL CHECK(kind IN ('bound','missing')),mas_user_id text,matrix_user_id text,CHECK((kind='bound' AND mas_user_id IS NOT NULL AND matrix_user_id IS NOT NULL) OR (kind='missing' AND mas_user_id IS NULL AND matrix_user_id IS NULL)),UNIQUE(id,operation_id,mapping_id,transition_revision),UNIQUE(operation_id,mapping_id,transition_revision),FOREIGN KEY(operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) ON DELETE RESTRICT);
CREATE TABLE control_plane.membership_access_registry_snapshots (id uuid PRIMARY KEY,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,kind text NOT NULL CHECK(kind IN ('complete','missing')),expected_room_count integer NOT NULL CHECK(expected_room_count>=0),target_digest bytea CHECK(octet_length(target_digest)=32),created_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),CHECK((kind='missing' AND expected_room_count=0 AND target_digest IS NULL) OR (kind='complete' AND target_digest IS NOT NULL)),UNIQUE(id,operation_id,mapping_id,transition_revision),UNIQUE(operation_id,mapping_id,transition_revision),FOREIGN KEY(operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) ON DELETE RESTRICT);
CREATE TABLE control_plane.membership_access_crypto_capabilities (id uuid PRIMARY KEY,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,kind text NOT NULL CHECK(kind IN ('supported','missing')),capability_version text,CHECK((kind='supported' AND capability_version IS NOT NULL) OR (kind='missing' AND capability_version IS NULL)),UNIQUE(id,operation_id,mapping_id,transition_revision),UNIQUE(operation_id,mapping_id,transition_revision),FOREIGN KEY(operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) ON DELETE RESTRICT);
CREATE TABLE control_plane.membership_access_room_targets (id uuid PRIMARY KEY,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,registry_snapshot_id uuid NOT NULL,room_id text NOT NULL CHECK(octet_length(room_id) BETWEEN 1 AND 255),moderator_user_id text NOT NULL CHECK(octet_length(moderator_user_id) BETWEEN 1 AND 255),UNIQUE(id,operation_id,mapping_id,transition_revision),UNIQUE(operation_id,mapping_id,transition_revision,room_id),FOREIGN KEY(operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(registry_snapshot_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_registry_snapshots(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT);
CREATE TABLE control_plane.membership_access_steps (id uuid PRIMARY KEY,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,step_kind text NOT NULL CHECK(step_kind IN ('mas_lock','mas_finish_sessions','mas_prerequisite','room_ban','registry_prerequisite','crypto_gate','crypto_prerequisite')),state text NOT NULL CHECK(state IN ('pending','leased','retry_wait','succeeded','blocked')),mas_target_id uuid,registry_snapshot_id uuid,crypto_capability_id uuid,room_target_id uuid,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),next_attempt_at timestamptz,lease_token bytea CHECK(octet_length(lease_token)=32),lease_generation bigint NOT NULL DEFAULT 0 CHECK(lease_generation>=0),lease_owner text,lease_expires_at timestamptz,error_code text CHECK(error_code ~ '^[a-z][a-z0-9_]{0,63}$'),confirmed_at timestamptz,evidence_fingerprint bytea CHECK(octet_length(evidence_fingerprint)=32),UNIQUE(id,operation_id,mapping_id,transition_revision),FOREIGN KEY(operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_operations(id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(mas_target_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_mas_targets(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(registry_snapshot_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_registry_snapshots(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(crypto_capability_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_crypto_capabilities(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(room_target_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_room_targets(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,CHECK((step_kind IN ('mas_lock','mas_finish_sessions','mas_prerequisite') AND mas_target_id IS NOT NULL AND registry_snapshot_id IS NULL AND crypto_capability_id IS NULL AND room_target_id IS NULL) OR (step_kind='room_ban' AND room_target_id IS NOT NULL AND mas_target_id IS NULL AND registry_snapshot_id IS NULL AND crypto_capability_id IS NULL) OR (step_kind='registry_prerequisite' AND registry_snapshot_id IS NOT NULL AND mas_target_id IS NULL AND crypto_capability_id IS NULL AND room_target_id IS NULL) OR (step_kind IN ('crypto_gate','crypto_prerequisite') AND crypto_capability_id IS NOT NULL AND mas_target_id IS NULL AND registry_snapshot_id IS NULL AND room_target_id IS NULL)),CHECK((state='leased')=(lease_token IS NOT NULL AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)),CHECK(confirmed_at IS NULL OR state='succeeded'),CHECK(evidence_fingerprint IS NULL OR state='succeeded'));
CREATE TABLE control_plane.membership_access_step_attempts (id uuid PRIMARY KEY,step_id uuid NOT NULL,operation_id uuid NOT NULL,mapping_id uuid NOT NULL,transition_revision bigint NOT NULL,event_kind text NOT NULL CHECK(event_kind IN ('claim','result','operator_retry')),prior_attempt_id uuid,lease_generation bigint,lease_token bytea CHECK(octet_length(lease_token)=32),owner text,claimed_at timestamptz,lease_expires_at timestamptz,outcome text CHECK(outcome IN ('succeeded','retry_wait','blocked')),error_code text CHECK(error_code ~ '^[a-z][a-z0-9_]{0,63}$'),evidence_fingerprint bytea CHECK(octet_length(evidence_fingerprint)=32),created_at timestamptz NOT NULL,UNIQUE(id,step_id,operation_id,mapping_id,transition_revision),FOREIGN KEY(step_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_steps(id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,FOREIGN KEY(prior_attempt_id,step_id,operation_id,mapping_id,transition_revision) REFERENCES control_plane.membership_access_step_attempts(id,step_id,operation_id,mapping_id,transition_revision) ON DELETE RESTRICT,CHECK((event_kind='claim')=(prior_attempt_id IS NULL AND lease_generation IS NOT NULL AND lease_token IS NOT NULL AND owner IS NOT NULL AND claimed_at IS NOT NULL AND lease_expires_at IS NOT NULL AND outcome IS NULL AND error_code IS NULL)),CHECK((event_kind='result')=(prior_attempt_id IS NOT NULL AND outcome IS NOT NULL AND lease_generation IS NOT NULL AND lease_token IS NOT NULL AND owner IS NOT NULL)),CHECK((event_kind='operator_retry')=(prior_attempt_id IS NOT NULL AND lease_generation IS NULL AND lease_token IS NULL AND owner IS NULL AND claimed_at IS NULL AND lease_expires_at IS NULL AND outcome IS NULL)));

CREATE FUNCTION control_plane.revocation_append_only_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'revocation foundation rows are append-only'; END $$;
CREATE TRIGGER membership_access_sources_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_sources FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_source_chunks_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_source_chunks FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_selectors_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_source_selector_aliases FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_causes_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_source_cause_aliases FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_targets_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_source_targets FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_requests_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_requests FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE TRIGGER membership_access_attempts_append_only BEFORE UPDATE OR DELETE ON control_plane.membership_access_step_attempts FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_append_only_guard();
CREATE FUNCTION control_plane.revocation_deferred_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE r jsonb:=to_jsonb(NEW); BEGIN IF TG_TABLE_NAME='did_mappings' AND NOT EXISTS(SELECT 1 FROM membership_access_states WHERE mapping_id=NEW.id) THEN RAISE EXCEPTION 'every mapping requires one access state'; END IF; IF TG_TABLE_NAME='entitlements' AND EXISTS(SELECT 1 FROM revocation_evidence_key_ids k CROSS JOIN (VALUES('issuer'),('issuer_key'),('policy')) v(kind) WHERE k.enabled AND NOT EXISTS(SELECT 1 FROM entitlement_evidence_aliases a WHERE a.entitlement_id=NEW.id AND a.evidence_kind=v.kind AND a.fingerprint_key_id=k.key_id)) THEN RAISE EXCEPTION 'entitlement requires every configured evidence alias'; END IF; IF TG_TABLE_NAME='membership_access_operations' AND (NOT EXISTS(SELECT 1 FROM membership_access_mas_targets WHERE operation_id=(r->>'id')::uuid AND mapping_id=(r->>'mapping_id')::uuid AND transition_revision=(r->>'transition_revision')::bigint) OR NOT EXISTS(SELECT 1 FROM membership_access_registry_snapshots WHERE operation_id=(r->>'id')::uuid AND mapping_id=(r->>'mapping_id')::uuid AND transition_revision=(r->>'transition_revision')::bigint) OR NOT EXISTS(SELECT 1 FROM membership_access_crypto_capabilities WHERE operation_id=(r->>'id')::uuid AND mapping_id=(r->>'mapping_id')::uuid AND transition_revision=(r->>'transition_revision')::bigint)) THEN RAISE EXCEPTION 'operation requires MAS registry and crypto evidence'; END IF; IF TG_TABLE_NAME='membership_access_registry_snapshots' AND r->>'kind'='complete' AND (SELECT count(*) FROM membership_access_room_targets WHERE registry_snapshot_id=(r->>'id')::uuid)<>(r->>'expected_room_count')::integer THEN RAISE EXCEPTION 'registry target count mismatch'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER did_mapping_access_state_guard AFTER INSERT OR UPDATE ON control_plane.did_mappings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_deferred_guard();
CREATE CONSTRAINT TRIGGER entitlement_evidence_guard AFTER INSERT OR UPDATE ON control_plane.entitlements DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_deferred_guard();
CREATE CONSTRAINT TRIGGER operation_evidence_guard AFTER INSERT OR UPDATE ON control_plane.membership_access_operations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_deferred_guard();
CREATE CONSTRAINT TRIGGER registry_target_guard AFTER INSERT OR UPDATE ON control_plane.membership_access_registry_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_deferred_guard();
CREATE INDEX membership_access_source_target_mapping_idx ON control_plane.membership_access_source_targets(mapping_id); CREATE INDEX membership_access_source_selector_lookup_idx ON control_plane.membership_access_source_selector_aliases(selector_kind,fingerprint_key_id,fingerprint); CREATE INDEX membership_access_source_cause_lookup_idx ON control_plane.membership_access_source_cause_aliases(fingerprint_key_id,fingerprint); CREATE INDEX membership_access_source_publication_idx ON control_plane.membership_access_sources(publication_state,requested_at); CREATE INDEX membership_access_steps_due_idx ON control_plane.membership_access_steps(next_attempt_at) WHERE state IN ('pending','retry_wait'); CREATE INDEX entitlement_evidence_alias_lookup_idx ON control_plane.entitlement_evidence_aliases(evidence_kind,fingerprint_key_id,fingerprint);
DO $$ DECLARE r text:=current_setting('control_plane.revocation_role'); BEGIN IF r IS NULL OR r='' THEN RAISE EXCEPTION 'revocation role is required'; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN RAISE EXCEPTION 'revocation role does not exist'; END IF; EXECUTE format('REVOKE ALL ON SCHEMA control_plane, oidc FROM %I',r); EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA control_plane, oidc FROM %I',r); EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA control_plane, oidc FROM %I',r); END $$;

-- The registry is an owner-only policy input.  These validators deliberately
-- compare sets, rather than merely checking that an alias is present.
ALTER TABLE control_plane.membership_access_sources ADD CONSTRAINT membership_access_source_kind_reason CHECK ((source_kind,reason) IN (('entitlement_expiry','entitlement_expired'),('signed_policy_revocation','policy_revoked'),('authenticated_issuer_revocation','issuer_revoked'),('authenticated_key_compromise','issuer_key_compromise'),('authenticated_lost_device','lost_device')));
ALTER TABLE control_plane.membership_access_sources ADD CONSTRAINT membership_access_source_id_reason_key UNIQUE(id,reason);
CREATE FUNCTION control_plane.revocation_aliases_valid(p_entitlement uuid DEFAULT NULL,p_source uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$
 SELECT CASE WHEN p_entitlement IS NOT NULL AND NOT EXISTS(SELECT 1 FROM entitlements WHERE id=p_entitlement) THEN true WHEN p_source IS NOT NULL AND NOT EXISTS(SELECT 1 FROM membership_access_sources WHERE id=p_source) THEN true WHEN p_entitlement IS NOT NULL THEN NOT EXISTS (
   (SELECT k.key_id,v.kind FROM revocation_evidence_key_ids k CROSS JOIN (VALUES ('issuer'),('issuer_key'),('policy')) v(kind) WHERE k.enabled EXCEPT SELECT fingerprint_key_id,evidence_kind FROM entitlement_evidence_aliases WHERE entitlement_id=p_entitlement)
   UNION ALL (SELECT fingerprint_key_id,evidence_kind FROM entitlement_evidence_aliases WHERE entitlement_id=p_entitlement EXCEPT SELECT k.key_id,v.kind FROM revocation_evidence_key_ids k CROSS JOIN (VALUES ('issuer'),('issuer_key'),('policy')) v(kind) WHERE k.enabled))
 ELSE NOT EXISTS (
   (SELECT k.key_id,CASE s.source_kind WHEN 'entitlement_expiry' THEN 'mapping' WHEN 'authenticated_lost_device' THEN 'mapping' WHEN 'signed_policy_revocation' THEN 'policy' WHEN 'authenticated_issuer_revocation' THEN 'issuer' ELSE 'issuer_key' END FROM revocation_evidence_key_ids k CROSS JOIN membership_access_sources s WHERE k.enabled AND s.id=p_source EXCEPT SELECT fingerprint_key_id,selector_kind FROM membership_access_source_selector_aliases WHERE source_id=p_source)
   UNION ALL (SELECT fingerprint_key_id,selector_kind FROM membership_access_source_selector_aliases WHERE source_id=p_source EXCEPT SELECT k.key_id,CASE s.source_kind WHEN 'entitlement_expiry' THEN 'mapping' WHEN 'authenticated_lost_device' THEN 'mapping' WHEN 'signed_policy_revocation' THEN 'policy' WHEN 'authenticated_issuer_revocation' THEN 'issuer' ELSE 'issuer_key' END FROM revocation_evidence_key_ids k CROSS JOIN membership_access_sources s WHERE k.enabled AND s.id=p_source))
 AND NOT EXISTS ((SELECT key_id FROM revocation_evidence_key_ids WHERE enabled EXCEPT SELECT fingerprint_key_id FROM membership_access_source_cause_aliases WHERE source_id=p_source) UNION ALL (SELECT fingerprint_key_id FROM membership_access_source_cause_aliases WHERE source_id=p_source EXCEPT SELECT key_id FROM revocation_evidence_key_ids WHERE enabled)) END $$;
CREATE FUNCTION control_plane.revocation_alias_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ DECLARE e uuid; s uuid; BEGIN
 IF TG_TABLE_NAME='revocation_evidence_key_ids' THEN IF EXISTS(SELECT 1 FROM entitlements x WHERE NOT revocation_aliases_valid(x.id,NULL)) OR EXISTS(SELECT 1 FROM membership_access_sources x WHERE NOT revocation_aliases_valid(NULL,x.id)) THEN RAISE EXCEPTION 'evidence registry change invalidates aliases'; END IF;
 ELSIF TG_TABLE_NAME='entitlement_evidence_aliases' THEN e:=CASE WHEN TG_OP='DELETE' THEN OLD.entitlement_id ELSE NEW.entitlement_id END; IF NOT revocation_aliases_valid(e,NULL) THEN RAISE EXCEPTION 'entitlement aliases must exactly match enabled evidence keys'; END IF;
 ELSIF TG_TABLE_NAME='membership_access_sources' THEN s:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF NOT revocation_aliases_valid(NULL,s) THEN RAISE EXCEPTION 'source aliases must exactly match enabled evidence keys'; END IF;
 ELSE s:=CASE WHEN TG_OP='DELETE' THEN OLD.source_id ELSE NEW.source_id END; IF NOT revocation_aliases_valid(NULL,s) THEN RAISE EXCEPTION 'source aliases must exactly match enabled evidence keys'; END IF; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER entitlement_alias_bidirectional AFTER INSERT OR UPDATE OR DELETE ON control_plane.entitlement_evidence_aliases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_alias_guard();
CREATE CONSTRAINT TRIGGER selector_alias_bidirectional AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_source_selector_aliases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_alias_guard();
CREATE CONSTRAINT TRIGGER cause_alias_bidirectional AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_source_cause_aliases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_alias_guard();
CREATE CONSTRAINT TRIGGER evidence_registry_bidirectional AFTER INSERT OR UPDATE OR DELETE ON control_plane.revocation_evidence_key_ids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_alias_guard();
CREATE CONSTRAINT TRIGGER source_alias_bidirectional AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_alias_guard();
CREATE FUNCTION control_plane.replace_entitlement_evidence_aliases(p_entitlement uuid,p_aliases jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ BEGIN
 IF jsonb_typeof(p_aliases)<>'array' THEN RAISE EXCEPTION 'aliases must be an array'; END IF;
 DELETE FROM entitlement_evidence_aliases WHERE entitlement_id=p_entitlement;
 INSERT INTO entitlement_evidence_aliases(entitlement_id,evidence_kind,fingerprint_key_id,fingerprint) SELECT p_entitlement,x.evidence_kind,x.fingerprint_key_id,decode(x.fingerprint,'hex') FROM jsonb_to_recordset(p_aliases) x(evidence_kind text,fingerprint_key_id text,fingerprint text);
 END $$;

-- Sources are immutable evidence; only publication fields have a guarded state
-- transition.  A final publication proves every chunk and target was observed.
DROP TRIGGER membership_access_sources_append_only ON control_plane.membership_access_sources;
CREATE FUNCTION control_plane.source_update_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF ROW(NEW.id,NEW.source_kind,NEW.reason,NEW.producer_id,NEW.source_event_id,NEW.source_event_digest,NEW.requested_at,NEW.source_effective_at,NEW.mapping_id) IS DISTINCT FROM ROW(OLD.id,OLD.source_kind,OLD.reason,OLD.producer_id,OLD.source_event_id,OLD.source_event_digest,OLD.requested_at,OLD.source_effective_at,OLD.mapping_id) OR NOT ((OLD.publication_state='pending' AND NEW.publication_state='publishing') OR (OLD.publication_state='publishing' AND NEW.publication_state='published')) THEN RAISE EXCEPTION 'source identity is immutable and publication transition is invalid'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_access_sources_guard BEFORE UPDATE OR DELETE ON control_plane.membership_access_sources FOR EACH ROW EXECUTE FUNCTION control_plane.source_update_guard();
CREATE FUNCTION control_plane.source_fanout_valid(p_source uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$
 WITH source AS (SELECT * FROM membership_access_sources WHERE id=p_source), expected AS (
  SELECT DISTINCT e.mapping_id FROM source s JOIN entitlements e ON e.status='active' AND ((s.source_kind IN ('entitlement_expiry','authenticated_lost_device') AND e.mapping_id=s.mapping_id) OR (s.source_kind NOT IN ('entitlement_expiry','authenticated_lost_device') AND NOT EXISTS (SELECT 1 FROM membership_access_source_selector_aliases a WHERE a.source_id=s.id AND NOT EXISTS (SELECT 1 FROM entitlement_evidence_aliases ea WHERE ea.entitlement_id=e.id AND ea.evidence_kind=a.selector_kind AND ea.fingerprint_key_id=a.fingerprint_key_id AND ea.fingerprint=a.fingerprint))))
 ), chunk_facts AS (
  SELECT c.chunk_no,c.target_count,c.chunk_digest,count(t.mapping_id)::integer actual_count,sha256(convert_to(COALESCE(string_agg(t.mapping_id::text,',' ORDER BY t.mapping_id),''),'UTF8')) actual_digest FROM membership_access_source_chunks c LEFT JOIN membership_access_source_targets t ON t.source_id=c.source_id AND t.chunk_no=c.chunk_no WHERE c.source_id=p_source GROUP BY c.chunk_no,c.target_count,c.chunk_digest
 ), summary AS (
  SELECT count(*)::integer chunk_count,COALESCE(sum(actual_count),0)::integer target_count,sha256(decode(COALESCE(string_agg(encode(chunk_digest,'hex'),'' ORDER BY chunk_no),''),'hex')) cursor_digest,bool_and(target_count=actual_count AND chunk_digest=actual_digest) chunks_valid,COALESCE(min(chunk_no),0) min_chunk,COALESCE(max(chunk_no),-1) max_chunk FROM chunk_facts
 ) SELECT COALESCE((SELECT revocation_aliases_valid(NULL,s.id) AND s.chunk_count=q.chunk_count AND q.min_chunk=0 AND q.max_chunk=q.chunk_count-1 AND q.target_count=(SELECT count(*) FROM expected) AND q.chunks_valid IS NOT FALSE AND s.cursor_digest=q.cursor_digest AND NOT EXISTS((SELECT mapping_id FROM expected EXCEPT SELECT mapping_id FROM membership_access_source_targets WHERE source_id=p_source) UNION ALL (SELECT mapping_id FROM membership_access_source_targets WHERE source_id=p_source EXCEPT SELECT mapping_id FROM expected)) FROM source s CROSS JOIN summary q),true) $$;
CREATE FUNCTION control_plane.source_fanout_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE s uuid; BEGIN s:=CASE WHEN TG_TABLE_NAME='membership_access_sources' THEN COALESCE((to_jsonb(NEW)->>'id')::uuid,(to_jsonb(OLD)->>'id')::uuid) ELSE COALESCE((to_jsonb(NEW)->>'source_id')::uuid,(to_jsonb(OLD)->>'source_id')::uuid) END;
 IF EXISTS(SELECT 1 FROM membership_access_sources WHERE id=s AND publication_state='published') AND NOT source_fanout_valid(s) THEN RAISE EXCEPTION 'published source fanout is incomplete'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER source_fanout_source AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.source_fanout_guard();
CREATE CONSTRAINT TRIGGER source_fanout_chunk AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_source_chunks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.source_fanout_guard();
CREATE CONSTRAINT TRIGGER source_fanout_target AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_source_targets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.source_fanout_guard();

CREATE FUNCTION control_plane.operation_shape_valid(p_operation uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$
 WITH op AS (SELECT id,mapping_id,transition_revision FROM membership_access_operations WHERE id=p_operation), expected(step_kind,mas_target_id,registry_snapshot_id,crypto_capability_id,room_target_id) AS (
  SELECT v.step_kind,m.id,NULL::uuid,NULL::uuid,NULL::uuid FROM op JOIN membership_access_mas_targets m ON (m.operation_id,m.mapping_id,m.transition_revision)=(op.id,op.mapping_id,op.transition_revision) CROSS JOIN LATERAL (SELECT 'mas_lock'::text WHERE m.kind='bound' UNION ALL SELECT 'mas_finish_sessions' WHERE m.kind='bound' UNION ALL SELECT 'mas_prerequisite' WHERE m.kind='missing') v(step_kind)
  UNION ALL SELECT 'registry_prerequisite',NULL,r.id,NULL,NULL FROM op JOIN membership_access_registry_snapshots r ON (r.operation_id,r.mapping_id,r.transition_revision)=(op.id,op.mapping_id,op.transition_revision) WHERE r.kind='missing'
  UNION ALL SELECT 'room_ban',NULL,NULL,NULL,t.id FROM op JOIN membership_access_registry_snapshots r ON (r.operation_id,r.mapping_id,r.transition_revision)=(op.id,op.mapping_id,op.transition_revision) JOIN membership_access_room_targets t ON (t.registry_snapshot_id,t.operation_id,t.mapping_id,t.transition_revision)=(r.id,op.id,op.mapping_id,op.transition_revision) WHERE r.kind='complete'
  UNION ALL SELECT CASE c.kind WHEN 'supported' THEN 'crypto_gate' ELSE 'crypto_prerequisite' END,NULL,NULL,c.id,NULL FROM op JOIN membership_access_crypto_capabilities c ON (c.operation_id,c.mapping_id,c.transition_revision)=(op.id,op.mapping_id,op.transition_revision)
 ), actual AS (SELECT step_kind,mas_target_id,registry_snapshot_id,crypto_capability_id,room_target_id FROM membership_access_steps WHERE operation_id=p_operation)
 SELECT COALESCE((SELECT (SELECT count(*) FROM membership_access_mas_targets WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_registry_snapshots WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_crypto_capabilities WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_room_targets WHERE operation_id=op.id)=(SELECT COALESCE(sum(expected_room_count) FILTER (WHERE kind='complete'),0) FROM membership_access_registry_snapshots WHERE operation_id=op.id) AND (SELECT count(*) FROM expected)=(SELECT count(*) FROM actual) AND NOT EXISTS((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) FROM op),true) $$;
CREATE FUNCTION control_plane.operation_shape_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE old_operation uuid; new_operation uuid; BEGIN
 old_operation:=CASE WHEN TG_OP='INSERT' THEN NULL WHEN TG_TABLE_NAME='membership_access_operations' THEN (to_jsonb(OLD)->>'id')::uuid ELSE (to_jsonb(OLD)->>'operation_id')::uuid END;
 new_operation:=CASE WHEN TG_OP='DELETE' THEN NULL WHEN TG_TABLE_NAME='membership_access_operations' THEN (to_jsonb(NEW)->>'id')::uuid ELSE (to_jsonb(NEW)->>'operation_id')::uuid END;
 IF old_operation IS NOT NULL AND NOT operation_shape_valid(old_operation) THEN RAISE EXCEPTION 'operation evidence and typed steps do not exactly match'; END IF;
 IF new_operation IS NOT NULL AND new_operation IS DISTINCT FROM old_operation AND NOT operation_shape_valid(new_operation) THEN RAISE EXCEPTION 'operation evidence and typed steps do not exactly match'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER operation_shape_operation AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_operations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();
CREATE CONSTRAINT TRIGGER operation_shape_mas AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_mas_targets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();
CREATE CONSTRAINT TRIGGER operation_shape_registry AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_registry_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();
CREATE CONSTRAINT TRIGGER operation_shape_crypto AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_crypto_capabilities DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();
CREATE CONSTRAINT TRIGGER operation_shape_room AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_room_targets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();
CREATE CONSTRAINT TRIGGER operation_shape_step AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_steps DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.operation_shape_guard();

ALTER TABLE control_plane.security_audit_events ADD COLUMN source_id uuid REFERENCES control_plane.membership_access_sources(id) ON DELETE RESTRICT, ADD COLUMN operation_id uuid REFERENCES control_plane.membership_access_operations(id) ON DELETE RESTRICT, ADD COLUMN step_id uuid REFERENCES control_plane.membership_access_steps(id) ON DELETE RESTRICT;
ALTER TABLE control_plane.security_audit_events DROP CONSTRAINT security_audit_events_type;
ALTER TABLE control_plane.security_audit_events DROP CONSTRAINT security_audit_events_reason;
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_type CHECK(event_type IN ('login_state_consumed','session_revoked','challenge_consumed','entitlement_decided','policy_activated','membership_access_source_published','membership_access_operation_terminal','membership_access_step_succeeded'));
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_reason CHECK(reason IN ('completed','expired','revoked','policy','authorization','entitlement_expired','policy_revoked','issuer_revoked','issuer_key_compromise','lost_device'));
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_source_reason_fkey FOREIGN KEY(source_id,reason) REFERENCES control_plane.membership_access_sources(id,reason) ON DELETE RESTRICT;
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_membership_evidence CHECK((event_type='membership_access_source_published' AND outcome='success' AND reason IN ('entitlement_expired','policy_revoked','issuer_revoked','issuer_key_compromise','lost_device') AND source_id IS NOT NULL AND operation_id IS NULL AND step_id IS NULL) OR (event_type='membership_access_operation_terminal' AND outcome='success' AND reason='completed' AND source_id IS NULL AND operation_id IS NOT NULL AND step_id IS NULL) OR (event_type='membership_access_step_succeeded' AND outcome='success' AND reason='completed' AND source_id IS NULL AND operation_id IS NULL AND step_id IS NOT NULL) OR (event_type NOT IN ('membership_access_source_published','membership_access_operation_terminal','membership_access_step_succeeded') AND source_id IS NULL AND operation_id IS NULL AND step_id IS NULL));
-- Serialize live fanout selection with entitlement dependency writes.
CREATE FUNCTION control_plane.entitlement_publication_fence() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE s uuid; m uuid:=COALESCE(NEW.mapping_id,OLD.mapping_id); BEGIN FOR s IN SELECT id FROM membership_access_sources WHERE publication_state IN ('pending','publishing','published') AND (mapping_id=m OR source_kind NOT IN ('entitlement_expiry','authenticated_lost_device')) ORDER BY id LOOP PERFORM pg_advisory_xact_lock(hashtextextended(s::text,5005)); IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM membership_access_sources x WHERE x.id=s AND x.publication_state='published' AND (x.mapping_id=NEW.mapping_id OR (x.source_kind NOT IN ('entitlement_expiry','authenticated_lost_device') AND NOT EXISTS(SELECT 1 FROM membership_access_source_selector_aliases a WHERE a.source_id=x.id AND NOT EXISTS(SELECT 1 FROM entitlement_evidence_aliases ea WHERE ea.entitlement_id=NEW.id AND ea.evidence_kind=a.selector_kind AND ea.fingerprint_key_id=a.fingerprint_key_id AND ea.fingerprint=a.fingerprint)))) AND NOT EXISTS(SELECT 1 FROM membership_access_source_targets t WHERE t.source_id=x.id AND t.mapping_id=NEW.mapping_id)) THEN RAISE EXCEPTION 'entitlement would make published source fanout incomplete'; END IF; END LOOP; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER entitlement_publication_fence BEFORE INSERT OR UPDATE OR DELETE ON control_plane.entitlements FOR EACH ROW EXECUTE FUNCTION control_plane.entitlement_publication_fence();
ALTER FUNCTION control_plane.entitlement_publication_fence() SECURITY DEFINER;
-- Alias insertion is part of making a new entitlement match a selector; it must
-- cross the same publication fence as the entitlement row itself.
CREATE FUNCTION control_plane.entitlement_alias_publication_fence() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE s uuid; m uuid; BEGIN IF TG_OP='DELETE' THEN RETURN OLD; END IF; SELECT mapping_id INTO m FROM entitlements WHERE id=NEW.entitlement_id; FOR s IN SELECT id FROM membership_access_sources WHERE publication_state IN ('pending','publishing','published') AND source_kind NOT IN ('entitlement_expiry','authenticated_lost_device') ORDER BY id LOOP PERFORM pg_advisory_xact_lock(hashtextextended(s::text,5005)); IF EXISTS(SELECT 1 FROM membership_access_sources x WHERE x.id=s AND x.publication_state='published' AND NOT EXISTS(SELECT 1 FROM membership_access_source_selector_aliases a WHERE a.source_id=x.id AND NOT (a.selector_kind=NEW.evidence_kind AND a.fingerprint_key_id=NEW.fingerprint_key_id AND a.fingerprint=NEW.fingerprint) AND NOT EXISTS(SELECT 1 FROM entitlement_evidence_aliases ea WHERE ea.entitlement_id=NEW.entitlement_id AND ea.evidence_kind=a.selector_kind AND ea.fingerprint_key_id=a.fingerprint_key_id AND ea.fingerprint=a.fingerprint)) AND NOT EXISTS(SELECT 1 FROM membership_access_source_targets t WHERE t.source_id=x.id AND t.mapping_id=m)) THEN RAISE EXCEPTION 'entitlement alias would make published source fanout incomplete'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER entitlement_alias_publication_fence BEFORE INSERT OR UPDATE OR DELETE ON control_plane.entitlement_evidence_aliases FOR EACH ROW EXECUTE FUNCTION control_plane.entitlement_alias_publication_fence();
ALTER FUNCTION control_plane.entitlement_alias_publication_fence() SECURITY DEFINER;
CREATE OR REPLACE FUNCTION control_plane.source_update_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'source identity is immutable and publication transition is invalid'; END IF; IF ROW(NEW.id,NEW.source_kind,NEW.reason,NEW.producer_id,NEW.source_event_id,NEW.source_event_digest,NEW.requested_at,NEW.source_effective_at,NEW.mapping_id,NEW.created_xid) IS DISTINCT FROM ROW(OLD.id,OLD.source_kind,OLD.reason,OLD.producer_id,OLD.source_event_id,OLD.source_event_digest,OLD.requested_at,OLD.source_effective_at,OLD.mapping_id,OLD.created_xid) OR NOT ((OLD.publication_state='pending' AND NEW.publication_state='publishing' AND OLD.created_xid<>pg_current_xact_id()) OR (OLD.publication_state='publishing' AND NEW.publication_state='published')) THEN RAISE EXCEPTION 'source identity is immutable and publication transition is invalid'; END IF; LOCK TABLE entitlements IN SHARE ROW EXCLUSIVE MODE; PERFORM pg_advisory_xact_lock(hashtextextended(NEW.id::text,5005)); RETURN NEW; END $$;

CREATE UNIQUE INDEX audit_source_published_once ON control_plane.security_audit_events(source_id) WHERE event_type='membership_access_source_published';
CREATE FUNCTION control_plane.alias_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'evidence alias identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER entitlement_evidence_alias_identity BEFORE UPDATE ON control_plane.entitlement_evidence_aliases FOR EACH ROW EXECUTE FUNCTION control_plane.alias_identity_guard();
-- Complete registry snapshots bind the exact canonical room/moderator byte set.
-- Each UTF-8 field is length-prefixed with PostgreSQL's network-order int4send.
CREATE FUNCTION control_plane.registry_target_digest(p_snapshot uuid) RETURNS bytea LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$ WITH records AS (SELECT int4send(octet_length(convert_to(t.room_id,'UTF8')))||convert_to(t.room_id,'UTF8')||int4send(octet_length(convert_to(t.moderator_user_id,'UTF8')))||convert_to(t.moderator_user_id,'UTF8') AS record FROM membership_access_room_targets t WHERE t.registry_snapshot_id=p_snapshot) SELECT sha256(convert_to('dsa-signal-managed-room-targets:v1','UTF8')||E'\\000'::bytea||COALESCE((SELECT string_agg(record,''::bytea ORDER BY record) FROM records),'\\x'::bytea)) $$;
CREATE FUNCTION control_plane.registry_snapshot_valid(p_snapshot uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$ SELECT COALESCE((SELECT r.kind='missing' OR (r.expected_room_count=(SELECT count(*) FROM membership_access_room_targets t WHERE t.registry_snapshot_id=r.id) AND r.target_digest=registry_target_digest(r.id)) FROM membership_access_registry_snapshots r WHERE r.id=p_snapshot),true) $$;
CREATE FUNCTION control_plane.registry_snapshot_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE r uuid; BEGIN IF TG_TABLE_NAME='membership_access_registry_snapshots' THEN r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF TG_OP IN ('UPDATE','DELETE') THEN RAISE EXCEPTION 'registry snapshots are immutable'; END IF; ELSE r:=CASE WHEN TG_OP='DELETE' THEN OLD.registry_snapshot_id ELSE NEW.registry_snapshot_id END; IF EXISTS(SELECT 1 FROM membership_access_registry_snapshots x WHERE x.id=r AND (x.kind='missing' OR x.created_xid<>pg_current_xact_id())) THEN RAISE EXCEPTION 'registry targets are immutable'; END IF; END IF; IF NOT registry_snapshot_valid(r) THEN RAISE EXCEPTION 'registry target count or digest mismatch'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER registry_snapshot_digest_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_registry_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.registry_snapshot_guard();
CREATE CONSTRAINT TRIGGER registry_target_digest_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_room_targets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.registry_snapshot_guard();

CREATE UNIQUE INDEX audit_operation_terminal_once ON control_plane.security_audit_events(operation_id) WHERE event_type='membership_access_operation_terminal';
-- Audit facts are deferred lifecycle assertions and are rechecked from both sides.
CREATE FUNCTION control_plane.membership_audit_valid(p_audit uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$ SELECT COALESCE((SELECT CASE a.event_type WHEN 'membership_access_source_published' THEN EXISTS(SELECT 1 FROM membership_access_sources s WHERE s.id=a.source_id AND s.publication_state='published' AND a.mapping_id IS NOT DISTINCT FROM s.mapping_id) WHEN 'membership_access_operation_terminal' THEN EXISTS(SELECT 1 FROM membership_access_operations o WHERE o.id=a.operation_id AND o.state='completed' AND a.mapping_id=o.mapping_id) WHEN 'membership_access_step_succeeded' THEN EXISTS(SELECT 1 FROM membership_access_steps st WHERE st.id=a.step_id AND st.state='succeeded' AND a.mapping_id=st.mapping_id) ELSE true END FROM security_audit_events a WHERE a.id=p_audit),true) $$;
CREATE FUNCTION control_plane.membership_audit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE a uuid; r uuid; BEGIN IF TG_TABLE_NAME='security_audit_events' THEN a:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF NOT membership_audit_valid(a) THEN RAISE EXCEPTION 'audit event lifecycle is not true'; END IF; ELSIF TG_TABLE_NAME='membership_access_sources' THEN r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM membership_access_sources s WHERE s.id=r AND s.publication_state='published' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.source_id=s.id AND a.event_type='membership_access_source_published' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'published source requires exact audit'; END IF; ELSIF TG_TABLE_NAME='membership_access_operations' THEN r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM membership_access_operations o WHERE o.id=r AND o.state='completed' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=o.id AND a.event_type='membership_access_operation_terminal' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'completed operation requires exact audit'; END IF; ELSE r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM membership_access_steps st WHERE st.id=r AND st.state='succeeded' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.step_id=st.id AND a.event_type='membership_access_step_succeeded' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'succeeded step requires exact audit'; END IF; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER membership_audit_event_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.security_audit_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.membership_audit_guard();
CREATE CONSTRAINT TRIGGER membership_audit_source_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.membership_audit_guard();
CREATE CONSTRAINT TRIGGER membership_audit_operation_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_operations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.membership_audit_guard();
CREATE CONSTRAINT TRIGGER membership_audit_step_guard AFTER INSERT OR UPDATE OR DELETE ON control_plane.membership_access_steps DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION control_plane.membership_audit_guard();
ALTER FUNCTION control_plane.membership_audit_valid(uuid) SECURITY DEFINER;
ALTER FUNCTION control_plane.membership_audit_guard() SECURITY DEFINER;

CREATE UNIQUE INDEX audit_step_succeeded_once ON control_plane.security_audit_events(step_id) WHERE event_type='membership_access_step_succeeded';
-- Terminal lifecycle facts are monotonic.  This is intentionally a BEFORE
-- fence: a transaction must not be able to remove/reassociate its audit and
-- then demote the corresponding terminal record before deferred checks run.
CREATE FUNCTION control_plane.operation_terminal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF OLD.state='completed' AND (TG_OP='DELETE' OR ROW(NEW.id,NEW.mapping_id,NEW.transition_revision,NEW.state,NEW.first_effective_at,NEW.local_enforced_at,NEW.completed_at,NEW.blocked_code) IS DISTINCT FROM ROW(OLD.id,OLD.mapping_id,OLD.transition_revision,OLD.state,OLD.first_effective_at,OLD.local_enforced_at,OLD.completed_at,OLD.blocked_code)) THEN RAISE EXCEPTION 'completed operation is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_access_operations_terminal_guard BEFORE UPDATE OR DELETE ON control_plane.membership_access_operations FOR EACH ROW EXECUTE FUNCTION control_plane.operation_terminal_guard();
CREATE FUNCTION control_plane.step_terminal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF OLD.state='succeeded' AND (TG_OP='DELETE' OR ROW(NEW.id,NEW.operation_id,NEW.mapping_id,NEW.transition_revision,NEW.step_kind,NEW.state,NEW.mas_target_id,NEW.registry_snapshot_id,NEW.crypto_capability_id,NEW.room_target_id,NEW.attempt_count,NEW.next_attempt_at,NEW.lease_token,NEW.lease_generation,NEW.lease_owner,NEW.lease_expires_at,NEW.error_code,NEW.confirmed_at,NEW.evidence_fingerprint) IS DISTINCT FROM ROW(OLD.id,OLD.operation_id,OLD.mapping_id,OLD.transition_revision,OLD.step_kind,OLD.state,OLD.mas_target_id,OLD.registry_snapshot_id,OLD.crypto_capability_id,OLD.room_target_id,OLD.attempt_count,OLD.next_attempt_at,OLD.lease_token,OLD.lease_generation,OLD.lease_owner,OLD.lease_expires_at,OLD.error_code,OLD.confirmed_at,OLD.evidence_fingerprint)) THEN RAISE EXCEPTION 'succeeded step is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_access_steps_terminal_guard BEFORE UPDATE OR DELETE ON control_plane.membership_access_steps FOR EACH ROW EXECUTE FUNCTION control_plane.step_terminal_guard();
CREATE OR REPLACE FUNCTION control_plane.operation_shape_valid(p_operation uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,control_plane AS $$
 WITH op AS (SELECT id,mapping_id,transition_revision,state FROM membership_access_operations WHERE id=p_operation), expected(step_kind,mas_target_id,registry_snapshot_id,crypto_capability_id,room_target_id) AS (
  SELECT v.step_kind,m.id,NULL::uuid,NULL::uuid,NULL::uuid FROM op JOIN membership_access_mas_targets m ON (m.operation_id,m.mapping_id,m.transition_revision)=(op.id,op.mapping_id,op.transition_revision) CROSS JOIN LATERAL (SELECT 'mas_lock'::text WHERE m.kind='bound' UNION ALL SELECT 'mas_finish_sessions' WHERE m.kind='bound' UNION ALL SELECT 'mas_prerequisite' WHERE m.kind='missing') v(step_kind)
  UNION ALL SELECT 'registry_prerequisite',NULL,r.id,NULL,NULL FROM op JOIN membership_access_registry_snapshots r ON (r.operation_id,r.mapping_id,r.transition_revision)=(op.id,op.mapping_id,op.transition_revision) WHERE r.kind='missing'
  UNION ALL SELECT 'room_ban',NULL,NULL,NULL,t.id FROM op JOIN membership_access_registry_snapshots r ON (r.operation_id,r.mapping_id,r.transition_revision)=(op.id,op.mapping_id,op.transition_revision) JOIN membership_access_room_targets t ON (t.registry_snapshot_id,t.operation_id,t.mapping_id,t.transition_revision)=(r.id,op.id,op.mapping_id,op.transition_revision) WHERE r.kind='complete'
  UNION ALL SELECT CASE c.kind WHEN 'supported' THEN 'crypto_gate' ELSE 'crypto_prerequisite' END,NULL,NULL,c.id,NULL FROM op JOIN membership_access_crypto_capabilities c ON (c.operation_id,c.mapping_id,c.transition_revision)=(op.id,op.mapping_id,op.transition_revision)
 ), actual AS (SELECT step_kind,mas_target_id,registry_snapshot_id,crypto_capability_id,room_target_id FROM membership_access_steps WHERE operation_id=p_operation)
 SELECT COALESCE((SELECT (SELECT count(*) FROM membership_access_mas_targets WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_registry_snapshots WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_crypto_capabilities WHERE operation_id=op.id)=1 AND (SELECT count(*) FROM membership_access_room_targets WHERE operation_id=op.id)=(SELECT COALESCE(sum(expected_room_count) FILTER (WHERE kind='complete'),0) FROM membership_access_registry_snapshots WHERE operation_id=op.id) AND (SELECT count(*) FROM expected)=(SELECT count(*) FROM actual) AND NOT EXISTS((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) AND (op.state<>'completed' OR (NOT EXISTS(SELECT 1 FROM membership_access_steps st WHERE st.operation_id=op.id AND st.state<>'succeeded') AND EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=op.id AND a.event_type='membership_access_operation_terminal' AND a.outcome='success' AND a.reason='completed'))) FROM op),true) $$;
CREATE OR REPLACE FUNCTION control_plane.membership_audit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ DECLARE a uuid; r uuid; BEGIN IF TG_TABLE_NAME='security_audit_events' THEN a:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF NOT membership_audit_valid(a) THEN RAISE EXCEPTION 'audit event lifecycle is not true'; END IF; IF TG_OP IN ('UPDATE','DELETE') AND ((OLD.event_type='membership_access_source_published' AND EXISTS(SELECT 1 FROM membership_access_sources s WHERE s.id=OLD.source_id AND s.publication_state='published')) OR (OLD.event_type='membership_access_operation_terminal' AND EXISTS(SELECT 1 FROM membership_access_operations o WHERE o.id=OLD.operation_id AND o.state='completed')) OR (OLD.event_type='membership_access_step_succeeded' AND EXISTS(SELECT 1 FROM membership_access_steps st WHERE st.id=OLD.step_id AND st.state='succeeded'))) THEN RAISE EXCEPTION 'mandatory audit event cannot be removed or reassociated'; END IF; ELSIF TG_TABLE_NAME='membership_access_sources' THEN r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM security_audit_events a WHERE a.source_id=r AND NOT membership_audit_valid(a.id)) OR EXISTS(SELECT 1 FROM membership_access_sources s WHERE s.id=r AND s.publication_state='published' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.source_id=s.id AND a.event_type='membership_access_source_published' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'published source requires exact audit'; END IF; ELSIF TG_TABLE_NAME='membership_access_operations' THEN r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=r AND NOT membership_audit_valid(a.id)) OR EXISTS(SELECT 1 FROM membership_access_operations o WHERE o.id=r AND o.state='completed' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=o.id AND a.event_type='membership_access_operation_terminal' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'completed operation requires exact audit'; END IF; ELSE r:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; IF EXISTS(SELECT 1 FROM security_audit_events a WHERE a.step_id=r AND NOT membership_audit_valid(a.id)) OR EXISTS(SELECT 1 FROM membership_access_steps st WHERE st.id=r AND st.state='succeeded' AND NOT EXISTS(SELECT 1 FROM security_audit_events a WHERE a.step_id=st.id AND a.event_type='membership_access_step_succeeded' AND membership_audit_valid(a.id))) THEN RAISE EXCEPTION 'succeeded step requires exact audit'; END IF; END IF; RETURN NULL; END $$;
ALTER FUNCTION control_plane.membership_audit_guard() SECURITY DEFINER;
CREATE OR REPLACE FUNCTION control_plane.cleanup_expired(audit_before timestamptz) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ DECLARE removed bigint:=0; affected bigint; BEGIN
 PERFORM pg_advisory_xact_lock_shared(8004); IF audit_before>clock_timestamp()-interval '90 days' THEN RAISE EXCEPTION 'audit retention is 90 days'; END IF;
 DELETE FROM login_states WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM proof_challenges WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM identity_sessions WHERE absolute_expires_at+interval '30 seconds'<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM idempotency_results WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM jti_uses WHERE retained_until<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
 DELETE FROM entitlements e WHERE expires_at+interval '30 seconds'<=clock_timestamp() AND EXISTS(SELECT 1 FROM membership_access_sources s JOIN membership_access_source_targets t ON t.source_id=s.id AND t.mapping_id=e.mapping_id JOIN membership_access_states st ON st.mapping_id=e.mapping_id WHERE s.source_kind='entitlement_expiry' AND s.publication_state='published' AND st.barrier_state='suspended'); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
 DELETE FROM security_audit_events a WHERE occurred_at<audit_before AND a.event_type NOT IN ('membership_access_source_published','membership_access_operation_terminal','membership_access_step_succeeded'); GET DIAGNOSTICS affected=ROW_COUNT; RETURN removed+affected; END $$;
